wner_approved'):?><button class="pill" name="action" value="publish">Validar y publicar esta versión aprobada</button><?php endif ?><?php if($admin&&in_array($v['status'],['in_editorial','awaiting_owner','owner_approved'],true)):?><label>Motivo de rechazo<textarea name="note" maxlength="2000" rows="3"></textarea></label><button class="pill light" name="action" value="reject">Rechazar esta versión e informar el motivo</button><?php endif ?></form><?php endif ?><?php endif ?></section></main><?php require dirname(__DIR__).'/_business-map-dialog.php';?><script src="/assets/leaflet.js"></script><script src="/assets/admin-business-location.js?v=17" defer></script><script src="<?=esc(admin_asset('business-editorial.js'))?>" defer></script><script src="/assets/account-files.js?v=1" defer></script></body></html>
